package com.oldbutgold.shop.modules.commerce.application;
import com.oldbutgold.shop.modules.commerce.api.VoucherDtos.*;
import com.oldbutgold.shop.modules.commerce.infrastructure.persistence.VoucherWalletRepository;
import com.oldbutgold.shop.modules.identity.application.VoucherIdentityFacade;
import com.oldbutgold.shop.modules.catalog.application.CatalogCommerceFacade;
import com.oldbutgold.shop.modules.platform.application.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.access.AccessDeniedException;
import java.time.*;
import java.util.*;
import java.math.BigDecimal;
import static com.oldbutgold.shop.modules.platform.application.PlatformNotificationFacade.*;

@Service @Transactional
public class VoucherService {
    private final VoucherWalletRepository repo;private final VoucherIdentityFacade identity;private final CatalogCommerceFacade catalog;
    private final VoucherHistoryFacade audit;private final PlatformNotificationFacade notices;private final Clock clock;private final ObjectMapper json;
    public VoucherService(VoucherWalletRepository repo,VoucherIdentityFacade identity,CatalogCommerceFacade catalog,VoucherHistoryFacade audit,PlatformNotificationFacade notices,Clock clock,ObjectMapper json){this.repo=repo;this.identity=identity;this.catalog=catalog;this.audit=audit;this.notices=notices;this.clock=clock;this.json=json;}
    private Campaign campaign(long id,boolean lock){return repo.campaign(id,lock).orElseThrow(()->new IllegalArgumentException("Không tìm thấy chương trình voucher."));}
    private void version(Campaign c,long version){if(c.version()!=version)throw new IllegalArgumentException("Chương trình đã thay đổi. Hãy tải lại và xem trước danh sách.");}
    @Transactional(readOnly=true) public List<Campaign> campaigns(long actor,String role){identity.staff(actor,role);return repo.campaigns();}
    public Campaign save(long actor,Long id,Save s){identity.staff(actor,"ADMIN");String key="voucher:save:"+actor+":"+s.commandId();repo.lock(key);Map<String,Object> request=request(Map.of("id",id==null?0:id,"body",s));var prior=replay(actor,key,request,Campaign.class);if(prior!=null)return prior;
        Campaign old=id==null?null:campaign(id,true);if(old!=null){version(old,s.version());if(!old.code().equalsIgnoreCase(s.code().trim()))throw new IllegalArgumentException("Không đổi mã của chương trình đã tạo; hãy tạo chương trình mới.");if(s.quantity()<old.issued())throw new IllegalArgumentException("Hạn mức không thể nhỏ hơn số đã cấp.");}else if(s.version()!=0)throw new IllegalArgumentException("Phiên bản tạo mới không hợp lệ.");
        if(!s.endTime().isAfter(s.startTime())||((old==null||s.active())&&!s.endTime().isAfter(clock.instant())))throw new IllegalArgumentException("Ngày kết thúc phải sau ngày bắt đầu và sau hiện tại khi bật chương trình.");
        if(s.discountType().equals("PERCENTAGE")&&(s.discountValue().compareTo(new BigDecimal("100"))>0||s.maxDiscountAmount()==null))throw new IllegalArgumentException("Giảm theo phần trăm cần giá trị 1–100 và mức giảm tối đa.");
        if(s.scope().equals("PRODUCTS")&&(s.productIds().isEmpty()||s.voucherType().equals("SHIPPING_DISCOUNT")))throw new IllegalArgumentException("Phạm vi sản phẩm cần danh sách sản phẩm và voucher giảm tiền hàng.");
        if(s.scope().equals("CHECKOUT")&&!s.productIds().isEmpty())throw new IllegalArgumentException("Voucher toàn đơn không có danh sách sản phẩm.");
        if(new HashSet<>(s.productIds()).size()!=s.productIds().size())throw new IllegalArgumentException("Danh sách sản phẩm bị lặp.");
        if(s.active())for(long product:s.productIds())if(catalog.getActiveProduct(product).isEmpty())throw new IllegalArgumentException("Sản phẩm #"+product+" không mở bán.");
        long saved=repo.save(actor,id,s);Campaign result=campaign(saved,false);Map<String,Object> receipt=request(Map.of("value",result,"before",old==null?Map.of():old));audit.record(actor,saved,old==null?"CREATE":"UPDATE",key,request,receipt);notice(key,actor,Destination.ADMIN_VOUCHERS,saved,"VOUCHER_PROGRAM_UPDATED","Đã lưu chương trình voucher",result.code());return result;
    }
    private String issuing(Campaign c){Instant now=clock.instant();if(c.revisionId()==0)return "Chương trình chưa được cấu hình cho ví voucher";if(!c.active())return "Đang dừng phát";if(now.isBefore(c.startTime()))return "Chưa đến thời gian nhận";if(!now.isBefore(c.endTime()))return "Đã hết hạn";if(c.issued()>=c.quantity())return "Đã hết lượt phát";if(repo.revisionRevoked(c.revisionId()))return "Chính sách đã thu hồi";return "";}
    private String grantEligibility(Campaign c,VoucherIdentityFacade.Customer u){String reason=issuing(c);if(!reason.isEmpty())return reason;if(!u.eligible())return "Tài khoản không hoạt động";if(repo.received(c.id(),u.id())>0)return "Đã nhận chương trình này";return "";}
    private String revocable(Grant g){if(!g.state().equals("AVAILABLE"))return g.state().equals("REDEEMED")?"Voucher đã sử dụng":"Voucher đã thu hồi";if(!clock.instant().isBefore(g.expiresAt()))return "Voucher đã hết hạn";return "";}
    @Transactional(readOnly=true) public Wallet wallet(long user){var customer=identity.customer(user,false);List<Campaign> available=repo.campaigns().stream().filter(c->customer.eligible()&&c.selfClaim()&&issuing(c).isEmpty()&&repo.received(c.id(),user)==0).toList();return new Wallet(repo.owned(user),available,repo.points(user),repo.pointsHistory(user));}
    public Grant claim(long user,long id,Claim body){var u=identity.customer(user,false);String key="voucher:claim:"+user+":"+body.commandId();repo.lock(key);var request=request(Map.of("id",id,"body",body));Grant prior=replay(user,key,request,Grant.class);if(prior!=null)return prior;Campaign c=campaign(id,true);u=identity.customer(user,true);
        var existing=repo.owned(user).stream().filter(g->g.campaign().id()==id).findFirst();if(existing.isPresent()){audit.record(user,id,"CLAIM_REPLAY",key,request,request(Map.of("value",existing.get())));return existing.get();}version(c,body.version());if(!c.selfClaim())throw new IllegalArgumentException("Voucher này được KTV cấp trực tiếp.");String reason=grantEligibility(c,u);if(!reason.isEmpty())throw new IllegalArgumentException(reason);
        UUID grant=repo.grant(user,user,c,"SELF_CLAIM","Khách hàng nhận voucher",key,clock.instant());Grant result=repo.grant(grant,false).orElseThrow();audit.record(user,id,"CLAIM",key,request,request(Map.of("value",result)));notice(key,user,Destination.VOUCHER_WALLET,id,"VOUCHER_RECEIVED","Đã nhận voucher",c.code()+" đã có trong ví của bạn.");return result;
    }
    @Transactional(readOnly=true) public Targets targets(long actor,long id,String action,String query,String role,String status,boolean eligibleOnly,int page,int size){identity.staff(actor,"KTV");Campaign c=campaign(id,false);if(!Set.of("GRANT","REVOKE").contains(action)||!Set.of("ALL","BUYER","SELLER").contains(role)||!Set.of("ALL","ACTIVE","LOCKED","SUSPENDED","DEACTIVATED").contains(status))throw new IllegalArgumentException("Bộ lọc không hợp lệ.");int p=Math.max(0,page),s=Math.min(50,Math.max(1,size));Set<Long> include=action.equals("REVOKE")?repo.recipientIds(id,true,clock.instant()):null;Set<Long> exclude=action.equals("GRANT")&&eligibleOnly?repo.recipientIds(id,false,clock.instant()):Set.of();if(action.equals("GRANT")&&eligibleOnly&&!issuing(c).isEmpty())include=Set.of();var users=identity.search(query.trim(),role,eligibleOnly&&action.equals("GRANT")?"ACTIVE":status,p,s,include,exclude);List<Result> rows=new ArrayList<>();for(var u:users.items()){if(action.equals("GRANT")){String reason=grantEligibility(c,u);rows.add(new Result(Long.toString(u.id()),u.id(),u.name()+" · "+u.email(),reason.isEmpty(),"PREVIEW",reason,null));}else for(Grant g:repo.owned(u.id()))if(g.campaign().id()==id&&revocable(g).isEmpty())rows.add(new Result(g.id().toString(),u.id(),u.name()+" · "+u.email(),true,"PREVIEW","",g.id()));}return new Targets(rows,users.total(),p,s,c);}
    public Batch bulk(long actor,long id,Bulk body,boolean preview){identity.staff(actor,"KTV");if(!Set.of("GRANT","REVOKE").contains(body.action())||body.ids().isEmpty()||body.ids().size()>100||body.reason()==null||body.reason().isBlank())throw new IllegalArgumentException("Chọn 1–100 người và nhập lý do hợp lệ.");if(new HashSet<>(body.ids()).size()!=body.ids().size())throw new IllegalArgumentException("Danh sách bị lặp.");String key="voucher:bulk:"+actor+":"+body.commandId();repo.lock(key);var request=request(Map.of("id",id,"body",body));if(!preview){Batch prior=replay(actor,key,request,Batch.class);if(prior!=null)return prior;}Campaign c=campaign(id,true);version(c,body.version());List<Result> rows=new ArrayList<>();int issued=0;
        // Campaign lock serializes issuance limits; deterministic user locks also serialize account changes.
        Set<Long> locks=new TreeSet<>();for(String target:body.ids()){try{if(body.action().equals("GRANT"))locks.add(Long.parseLong(target));else repo.grant(UUID.fromString(target),false).ifPresent(g->locks.add(g.userId()));}catch(IllegalArgumentException e){throw new IllegalArgumentException("ID không hợp lệ.");}}identity.lockCustomers(locks);
        List<String> ordered=body.ids().stream().sorted().toList();for(String target:ordered){long user;Grant g=null;try{if(body.action().equals("GRANT"))user=Long.parseLong(target);else{g=repo.grant(UUID.fromString(target),true).orElse(null);if(g==null||g.campaign().id()!=id){rows.add(new Result(target,0,"",false,"SKIPPED","Không tìm thấy voucher thuộc chương trình",null));continue;}user=g.userId();}}catch(IllegalArgumentException e){throw new IllegalArgumentException("ID không hợp lệ.");}
            VoucherIdentityFacade.Customer u;try{u=identity.customer(user,true);}catch(AccessDeniedException e){rows.add(new Result(target,user,"",false,"SKIPPED","Người nhận không thuộc phạm vi khách hàng",null));continue;}
            String reason=body.action().equals("GRANT")?grantEligibility(c,u):revocable(g);if(body.action().equals("GRANT")&&reason.isEmpty()&&c.issued()+issued>=c.quantity())reason="Đã hết lượt phát";boolean ok=reason.isEmpty();UUID grant=g==null?null:g.id();
            if(ok){if(body.action().equals("GRANT")){issued++;if(!preview)grant=repo.grant(actor,user,c,"KTV_GIFT",body.reason().trim(),key+":"+user,clock.instant());}else if(!preview)repo.revoke(grant,actor,body.reason().trim(),key+":"+grant);if(!preview)notice(key+":"+target,user,Destination.VOUCHER_WALLET,id,body.action().equals("GRANT")?"VOUCHER_RECEIVED":"VOUCHER_REVOKED",body.action().equals("GRANT")?"Bạn được cấp voucher":"Voucher đã được thu hồi",c.code()+" · "+body.reason().trim());}
            rows.add(new Result(target,user,u.name(),ok,preview?"PREVIEW":ok?"SUCCESS":"SKIPPED",reason,grant));
        }
        long successful=rows.stream().filter(Result::eligible).count();Batch result=new Batch(rows,successful,rows.size()-successful);if(!preview){audit.record(actor,id,body.action(),key,request,request(Map.of("value",result)));notice(key,actor,Destination.KTV_VOUCHERS,id,"VOUCHER_BATCH_COMPLETED","Đã xử lý voucher",c.code()+": "+successful+" thành công, "+result.skipped()+" bỏ qua.");}return result;
    }
    /** Owned revision stays valid when Admin pauses/edits the campaign. */
    @Transactional(readOnly=true) public List<Grant> usable(long user,long product,BigDecimal subtotal){return repo.owned(user).stream().filter(g->usable(g,product,subtotal)).toList();}
    private boolean usable(Grant g,long product,BigDecimal subtotal){Campaign c=g.campaign();return revocable(g).isEmpty()&&!clock.instant().isBefore(c.startTime())&&subtotal.compareTo(c.minOrderAmount())>=0&&(c.scope().equals("CHECKOUT")||c.productIds().contains(product))&&!repo.revisionRevoked(c.revisionId());}
    public Grant resolve(long user,String code,long product,BigDecimal subtotal,boolean lock){var candidates=repo.owned(user).stream().filter(g->g.campaign().code().equalsIgnoreCase(code.trim())).toList();for(Grant candidate:candidates){Grant g=lock?repo.grant(candidate.id(),true).orElseThrow():candidate;if(usable(g,product,subtotal))return g;}throw new IllegalArgumentException("Voucher chưa có trong ví hoặc không đủ điều kiện cho đơn này.");}
    public void bindOrder(long order,Grant grant){repo.bindOrder(order,grant.id());}
    public void lockCheckout(long buyer,long seller){identity.lockCustomers(new TreeSet<>(List.of(buyer,seller)));}
    private void notice(String key,long user,Destination target,long campaign,String type,String title,String content){notices.enqueue(key,campaign,List.of(new Notice(user,type,title,content,target,campaign,0)));}
    private Map<String,Object> request(Object value){try{return json.readValue(json.writeValueAsString(value),new com.fasterxml.jackson.core.type.TypeReference<>(){});}catch(Exception e){throw new IllegalStateException("Cannot normalize voucher command",e);}}
    private <T>T replay(long actor,String key,Map<String,Object> request,Class<T> type){var receipt=audit.find(key);if(receipt.isEmpty())return null;var r=receipt.get();if(r.actorId()!=actor||!r.request().equals(request))throw new IllegalArgumentException("Mã thao tác đã được dùng cho nội dung khác.");return json.convertValue(r.result().get("value"),type);}
}
